<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { computed } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import { route } from 'ziggy-js';

type Option = { id: number; name: string };
type Period = { id: number; month: number; year: number; status: string };
type Row = { target_nik?: string | null; target_name: string; target_position?: string | null; evaluator_nik?: string | null; evaluator_name: string; evaluator_position?: string | null; evaluator_departments?: string | null; evaluator_factories?: string | null };
type Paginator = { data: Row[]; total: number; current_page: number; per_page: number; last_page: number; links: { url: string | null; label: string; active: boolean }[] };
const props = defineProps<{ periods: Period[]; selectedPeriod: Period | null; positions: Option[]; departments: Option[]; factories: Option[]; filters: Record<string, number | null>; rows: Paginator }>();
const filters = { ...props.filters };
const canExport = computed(() => filters.period !== null);
const apply = () => router.get(route('admin.reports.pending-evaluations'), filters, { preserveState: true, replace: true });
const exportUrl = () => route('admin.reports.pending-evaluations.export', Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== null)));
</script>

<template>
    <Head title="Daftar Belum Menilai" />
    <AdminLayout title="Daftar Belum Menilai">
        <div class="space-y-4">
            <div class="grid gap-3 rounded-xl bg-white p-5 sm:grid-cols-2 lg:grid-cols-3"><label class="text-sm font-semibold">Periode<select v-model="filters.period" class="mt-1 w-full rounded-lg border-slate-300"><option :value="null">Pilih periode</option><option v-for="period in periods" :key="period.id" :value="period.id">{{ period.month }}/{{ period.year }} · {{ period.status }}</option></select></label><label class="text-sm font-semibold">Jabatan yang dinilai<select v-model="filters.target_position_id" class="mt-1 w-full rounded-lg border-slate-300"><option :value="null">Semua</option><option v-for="position in positions" :key="position.id" :value="position.id">{{ position.name }}</option></select></label><label class="text-sm font-semibold">Jabatan belum menilai<select v-model="filters.evaluator_position_id" class="mt-1 w-full rounded-lg border-slate-300"><option :value="null">Semua</option><option v-for="position in positions" :key="position.id" :value="position.id">{{ position.name }}</option></select></label><label class="text-sm font-semibold">Departemen target<select v-model="filters.department_id" class="mt-1 w-full rounded-lg border-slate-300"><option :value="null">Semua</option><option v-for="department in departments" :key="department.id" :value="department.id">{{ department.name }}</option></select></label><label class="text-sm font-semibold">Lokasi/pabrik target<select v-model="filters.factory_id" class="mt-1 w-full rounded-lg border-slate-300"><option :value="null">Semua</option><option v-for="factory in factories" :key="factory.id" :value="factory.id">{{ factory.name }}</option></select></label><div class="flex items-end gap-2"><button type="button" class="rounded-lg bg-blue-700 px-4 py-2 font-semibold text-white" @click="apply">Tampilkan</button><a v-if="canExport" :href="exportUrl()" class="rounded-lg border border-slate-300 px-4 py-2 font-semibold">Export CSV</a><button v-else type="button" disabled class="cursor-not-allowed rounded-lg border border-slate-200 px-4 py-2 font-semibold text-slate-400">Export CSV</button></div></div>
            <div class="rounded-xl bg-white p-5"><p class="text-sm text-slate-500">{{ selectedPeriod ? `Periode ${selectedPeriod.month}/${selectedPeriod.year}` : 'Pilih periode' }} · {{ rows.total }} pasangan belum menilai</p></div>
            <div class="overflow-hidden rounded-xl border border-slate-200 bg-white"><div class="overflow-x-auto"><table class="w-full min-w-[1100px] text-left text-sm"><thead class="bg-amber-50 text-amber-900"><tr><th class="p-3">No.</th><th class="p-3">NIK yang Dinilai</th><th class="p-3">Nama yang Dinilai</th><th class="p-3">Jabatan yang Dinilai</th><th class="p-3">NIK Belum Menilai</th><th class="p-3">Nama Belum Menilai</th><th class="p-3">Jabatan Belum Menilai</th><th class="p-3">Departemen Belum Menilai</th><th class="p-3">Lokasi/Pabrik Belum Menilai</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="(row, index) in rows.data" :key="`${row.target_nik}-${row.evaluator_nik}`"><td class="p-3">{{ (rows.current_page - 1) * rows.per_page + index + 1 }}</td><td class="p-3">{{ row.target_nik ?? '-' }}</td><td class="p-3 font-semibold">{{ row.target_name }}</td><td class="p-3">{{ row.target_position ?? '-' }}</td><td class="p-3">{{ row.evaluator_nik ?? '-' }}</td><td class="p-3 font-semibold">{{ row.evaluator_name }}</td><td class="p-3">{{ row.evaluator_position ?? '-' }}</td><td class="p-3">{{ row.evaluator_departments ?? '-' }}</td><td class="p-3">{{ row.evaluator_factories ?? '-' }}</td></tr><tr v-if="!rows.data.length"><td colspan="9" class="p-8 text-center text-slate-500">Tidak ada data yang belum menilai.</td></tr></tbody></table></div><div v-if="rows.links.length > 3" class="flex flex-wrap gap-2 border-t border-slate-200 p-4"><template v-for="link in rows.links" :key="link.label"><Link v-if="link.url" :href="link.url" class="rounded-lg border px-3 py-1.5 text-sm" :class="link.active ? 'border-blue-700 bg-blue-700 text-white' : 'border-slate-300'" v-html="link.label" /><span v-else class="rounded-lg border border-slate-200 px-3 py-1.5 text-sm text-slate-400" v-html="link.label" /></template></div></div>
        </div>
    </AdminLayout>
</template>
